// BEGIN Generated by scripts/widget-assets.mjs from contracts/widget-assets.json. Do not edit.
/// zero's palette, light and dark. On iOS 26+ Home Screens the system tints
/// or glasses widgets itself (accented rendering); these apply in full colour.
enum ZeroColors {
  static let warning = dynamic(light: 0x8F5300, dark: 0xFFB74D)
  static let accent = dynamic(light: 0x6E8B3D, dark: 0xB1FB98)
  static let onAccent = dynamic(light: 0xFFFFFF, dark: 0x0F2A06)
  static let surface = dynamic(light: 0xFAFAF8, dark: 0x1A1A1A)
// END generated
  private static func dynamic(light: UInt32, dark: UInt32) -> Color {
    Color(UIColor { $0.userInterfaceStyle == .dark ? rgb(dark) : rgb(light) })
  }

  private static func rgb(_ hex: UInt32) -> UIColor {
    UIColor(
      red: CGFloat((hex >> 16) & 0xFF) / 255, green: CGFloat((hex >> 8) & 0xFF) / 255,
      blue: CGFloat(hex & 0xFF) / 255, alpha: 1)
  }
}

/// This month's figures as a card: Siri's and Spotlight's answer to "how much
/// have I spent". Read-only.
struct SpendingCard: View {
  let s: WidgetSnapshot
  var body: some View {
    VStack(alignment: .leading, spacing: 4) {
      Text(s.monthLabel).font(.subheadline).foregroundStyle(.secondary)
      Text(s.spentMonth)
        .font(.system(size: 34, weight: .semibold, design: .rounded))
        .monospacedDigit()
        .lineLimit(1)
        .minimumScaleFactor(0.5)
      HStack(spacing: 4) {
        Text(s.labels.today).foregroundStyle(.secondary)
        Text(s.spentToday).fontWeight(.medium)
      }
      .font(.subheadline)
      if let budget = s.budget {
        Text(budget.text).font(.footnote).foregroundStyle(budget.over ? ZeroColors.warning : Color.secondary)
      }
      if let income = s.incomeLine {
        Text(income).font(.footnote).foregroundStyle(.secondary)
      }
    }
    .frame(maxWidth: .infinity, alignment: .leading)
    .padding()
    .accessibilityElement(children: .combine)
  }
}

/// One "add again" entry as a full-width button: "Chai · Food   + ₹20".
/// Tapping it adds the entry once more; zero does not open.
@available(iOS 17.0, *)
struct AgainButton: View {
  let again: WidgetSnapshot.Again
  var compact = false
  var body: some View {
    Button(intent: AddAgainIntent(again)) {
      HStack(spacing: 8) {
        Image(systemName: "plus")
          .font(.system(size: compact ? 11 : 13, weight: .bold))
          .foregroundStyle(ZeroColors.accent)
          .widgetAccentable()
        VStack(alignment: .leading, spacing: 0) {
          Text(again.title).font((compact ? Font.caption : Font.subheadline).weight(.medium)).lineLimit(1)
          if again.title != again.categoryName && !compact {
            Text(again.categoryName).font(.caption2).foregroundStyle(.secondary).lineLimit(1)
          }
        }
        Spacer(minLength: 4)
        Text(again.amountText)
          .font((compact ? Font.caption : Font.subheadline).weight(.semibold))
          .monospacedDigit()
          .lineLimit(1)
          .privacySensitive()
      }
      .padding(.horizontal, 10)
      .padding(.vertical, compact ? 5 : 8)
      .frame(maxWidth: .infinity)
      .background(RoundedRectangle(cornerRadius: 10, style: .continuous).fill(ZeroColors.accent.opacity(0.12)))
      .contentShape(Rectangle())
    }
    .buttonStyle(.plain)
    .accessibilityLabel("\(String(localized: "intents_again")): \(again.title), \(again.amountText)")
  }
}

/// "Added ₹120 · Food   Undo", while the last entry made outside the app can still be taken back.
@available(iOS 17.0, *)
struct UndoBar: View {
  let last: LastAdded
  var body: some View {
    HStack(spacing: 6) {
      Image(systemName: "checkmark.circle.fill").foregroundStyle(ZeroColors.accent).widgetAccentable()
      Text("\(String(localized: "intents_added")) \(last.label)").font(.caption.weight(.medium)).lineLimit(1)
      Spacer(minLength: 4)
      Button(intent: UndoEntryIntent(id: last.id)) {
        Text("intents_undo").font(.caption.weight(.semibold)).foregroundStyle(ZeroColors.accent)
      }
      .buttonStyle(.plain)
    }
  }
}

// MARK: - The "add again" snippet (iOS 26+: buttons work inside Siri and Spotlight)

/// "Add again in zero": this month's figures with the "add again" entries as
/// buttons and Undo for the last one, all working in place.
@available(iOS 26.0, *)
struct AgainSnippetIntent: SnippetIntent {
  static let title: LocalizedStringResource = "intents_again"
  static let isDiscoverable = false

  func perform() async throws -> some IntentResult & ShowsSnippetView {
    // Called again after every button: always read the store afresh.
    let snapshot = SharedStore.snapshot()?.asOf(Date())
    return .result(view: AgainSnippetView(snapshot: snapshot, last: SharedStore.lastAdded()))
  }
}

@available(iOS 26.0, *)
struct AgainMenuIntent: AppIntent {
  static let title: LocalizedStringResource = "intents_again"
  static let description = IntentDescription("intents_again_description")

  func perform() async throws -> some IntentResult & ShowsSnippetIntent {
    guard let snapshot = SharedStore.snapshot(), snapshot.ready else { throw ZeroIntentError.notReady }
    return .result(snippetIntent: AgainSnippetIntent())
  }
}

@available(iOS 17.0, *)
struct AgainSnippetView: View {
  let snapshot: WidgetSnapshot?
  let last: LastAdded?
  var body: some View {
    VStack(alignment: .leading, spacing: 8) {
      if let s = snapshot, s.ready {
        HStack(alignment: .firstTextBaseline) {
          Text(s.monthLabel).font(.subheadline).foregroundStyle(.secondary)
          Spacer()
          Text(s.spentMonth).font(.title3.weight(.semibold)).monospacedDigit().contentTransition(.numericText())
        }
        let again = s.again ?? []
        if again.isEmpty {
          Text("intents_again_empty").font(.footnote).foregroundStyle(.secondary)
        } else {
          ForEach(again, id: \.self) { AgainButton(again: $0) }
        }
        if let last { UndoBar(last: last) }
      } else {
        Text("intents_not_ready").font(.footnote)
      }
    }
    .padding()
  }
}
